diff --git a/skills/comprehende/references/review.schema.json b/skills/comprehende/references/review.schema.json
index 6886bf5..ebcf9db 100644
--- a/skills/comprehende/references/review.schema.json
+++ b/skills/comprehende/references/review.schema.json
@@ -70,6 +70,30 @@
         "minLength": 1
       }
     },
+    "parts": {
+      "description": "One entry per independent story when groups use part. name matches group part. summary is that story's one-sentence what.",
+      "type": "array",
+      "items": {
+        "type": "object",
+        "properties": {
+          "name": {
+            "type": "string",
+            "minLength": 1,
+            "description": "Short name of the independent story. Same string as group part."
+          },
+          "summary": {
+            "type": "string",
+            "minLength": 1,
+            "description": "One sentence: what this independent story is."
+          }
+        },
+        "required": [
+          "name",
+          "summary"
+        ],
+        "additionalProperties": false
+      }
+    },
     "groups": {
       "type": "array",
       "items": {
@@ -127,8 +151,11 @@
           "hunkRefs": {
             "type": "array",
             "items": {
-              "$ref": "#/$defs/hunkRef"
-            }
+              "type": "string",
+              "minLength": 1,
+              "description": "A git path (every live hunk of that file), or path@oldStart+newStart. A rename is old -> new@oldStart+newStart."
+            },
+            "description": "A path string covers every live hunk of that file. path@oldStart+newStart is one hunk. old -> new@oldStart+newStart is a renamed hunk."
           }
         },
         "required": [
@@ -230,44 +257,6 @@
         "label"
       ],
       "additionalProperties": false
-    },
-    "hunkRef": {
-      "type": "object",
-      "properties": {
-        "path": {
-          "type": "string",
-          "minLength": 1
-        },
-        "oldPath": {
-          "type": "string",
-          "minLength": 1
-        },
-        "oldStart": {
-          "type": "integer",
-          "minimum": 0
-        },
-        "oldLines": {
-          "type": "integer",
-          "minimum": 0
-        },
-        "newStart": {
-          "type": "integer",
-          "minimum": 0
-        },
-        "newLines": {
-          "type": "integer",
-          "minimum": 0
-        }
-      },
-      "required": [
-        "path",
-        "oldStart",
-        "oldLines",
-        "newStart",
-        "newLines"
-      ],
-      "additionalProperties": false,
-      "description": "Copy from comprehende index. Identity is (path, oldStart, newStart), plus oldPath when renamed."
     }
   }
 }
